package android.content;
import java.util.*;import android.net.Uri;
public class Intent{public static final String ACTION_SEND="send",ACTION_SEND_MULTIPLE="send_multiple",EXTRA_SUBJECT="subject",EXTRA_TEXT="text",EXTRA_STREAM="stream",EXTRA_EMAIL="email";public static final int FLAG_GRANT_READ_URI_PERMISSION=1;private final String action;private String type;private int flags;private ClipData clip;private final Map<String,Object> extras=new HashMap<>();public Intent(String a){action=a;}public Intent setType(String t){type=t;return this;}public Intent addFlags(int f){flags|=f;return this;}public Intent putExtra(String k,Object v){extras.put(k,v);return this;}public Intent putParcelableArrayListExtra(String k,ArrayList<Uri> v){extras.put(k,v);return this;}public void setClipData(ClipData c){clip=c;}public ClipData getClipData(){return clip;}public String getAction(){return action;}public String getType(){return type;}public int getFlags(){return flags;}public String getStringExtra(String k){return (String)extras.get(k);}public String[] getStringArrayExtra(String k){return (String[])extras.get(k);}@SuppressWarnings("unchecked")public <T>ArrayList<T> getParcelableArrayListExtra(String k){return (ArrayList<T>)extras.get(k);}}
